class Box:
    pass

@test("Suppress swallows the listed exception")
def _():
    with Suppress(KeyError) as s:
        {}["missing"]
    assert isinstance(s.caught, KeyError), f"caught = {s.caught!r}"

@test("Suppress also swallows subclasses")
def _():
    with Suppress(LookupError) as s:
        [][1]
    assert isinstance(s.caught, IndexError)

@test("other exceptions propagate")
def _():
    def body():
        with Suppress(KeyError):
            raise ValueError("not mine")
    e = raises(ValueError, body)
    assert str(e) == "not mine"

@test("caught is None when nothing was raised")
def _():
    with Suppress(KeyError) as s:
        pass
    assert s.caught is None

@test("temporary_attr sets, then restores")
def _():
    b = Box(); b.mode = "normal"
    with temporary_attr(b, "mode", "debug"):
        assert b.mode == "debug"
    assert b.mode == "normal", f"mode is {b.mode!r} after the block"

@test("temporary_attr restores even when the block raises")
def _():
    b = Box(); b.mode = "normal"
    def body():
        with temporary_attr(b, "mode", "debug"):
            raise RuntimeError("boom")
    raises(RuntimeError, body)
    assert b.mode == "normal", f"mode is {b.mode!r} after an exception"

@test("temporary_attr removes an attribute that didn't exist")
def _():
    b = Box()
    with temporary_attr(b, "flag", True):
        assert b.flag is True
    assert not hasattr(b, "flag"), "flag should be gone after the block"

@test("nested temporary_attr calls unwind correctly")
def _():
    b = Box(); b.level = 0
    with temporary_attr(b, "level", 1):
        with temporary_attr(b, "level", 2):
            assert b.level == 2
        assert b.level == 1
    assert b.level == 0

