from contextlib import contextmanager


class Suppress:
    def __init__(self, *exception_types):
        self.exception_types = exception_types
        self.caught = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc_type is not None and issubclass(exc_type, self.exception_types):
            self.caught = exc
            return True  # a true return value tells Python the exception was handled
        return False


_MISSING = object()  # a sentinel: None could be a real attribute value


@contextmanager
def temporary_attr(obj, name, value):
    old = getattr(obj, name, _MISSING)
    setattr(obj, name, value)
    try:
        yield obj
    finally:  # runs whether the block finished or raised
        if old is _MISSING:
            delattr(obj, name)
        else:
            setattr(obj, name, old)
